  HV.makeInstance = function makeInstance(defOrId, rng, affixRarity) {
    const def = typeof defOrId === 'string' ? HV.ITEM_BY_ID[defOrId] : defOrId;
    if (!def) return null;
    const inst = {
      instId: HV.id('it'),
      id: def.id,
      name: def.name,
      slot: def.slot,
      rarity: def.rarity,
      unique: !!def.unique,
      set: def.set || null,
      flavor: def.flavor || '',
      stats: Object.assign({}, def.stats || {}),
      effects: (def.effects || []).map((e) => Object.assign({}, e)),
      identified: true,
    };
    if (!inst.unique && affixRarity && HV.AFFIXES[affixRarity] && rng) {
      const aff = HV.pick(rng, HV.AFFIXES[affixRarity]);
      inst.name = def.name + ' ' + aff.name;
      inst.rarity = affixRarity;
      inst.affix = aff.name;
      const st = inst.stats;
      Object.keys(aff.stats).forEach((k) => { st[k] = (st[k] || 0) + aff.stats[k]; });
    }
    return inst;
  };

  HV.rollLoot = function rollLoot(ctx) {
    const rng = ctx.rng || HV.rng('loot');
    const luck = ctx.luck || 0;
    const table = ctx.table || 'standard';
    const forced = ctx.forced;
    if (forced) return HV.makeInstance(forced, rng);

    const bossUniques = HV.UNIQUES.filter((u) => u.drop && u.drop.boss && u.drop.boss === ctx.boss);
    if (bossUniques.length && (ctx.guaranteed || rng() < 0.7 + luck)) {
      return HV.makeInstance(HV.pick(rng, bossUniques), rng);
    }
    const areaUniques = HV.UNIQUES.filter((u) => u.drop && u.drop.chest === ctx.area);
    if (areaUniques.length && rng() < 0.22 + luck * 0.3) {
      return HV.makeInstance(HV.pick(rng, areaUniques), rng);
    }

    let r = rng() - luck * 0.08;
    if (table === 'boss') r -= 0.15;
    if (table === 'cache') r -= 0.08;
    if (table === 'chest') r -= 0.05;
    let rarity = 'common';
    if (r < 0.06) rarity = 'rare';
    else if (r < 0.28) rarity = 'uncommon';
    const pool = HV.BASE_ITEMS.filter((i) => {
      const rank = HV.RARITY[i.rarity].rank;
      const want = HV.RARITY[rarity].rank;
      return rank <= want;
    });
    const base = HV.pick(rng, pool.length ? pool : HV.BASE_ITEMS);
    const affixRarity = HV.RARITY[rarity].rank > HV.RARITY[base.rarity].rank ? rarity : (rarity === 'rare' && rng() < 0.6 ? 'rare' : (rarity === 'uncommon' ? 'uncommon' : null));
    return HV.makeInstance(base, rng, affixRarity);
  };

  HV.equippedSetCounts = function equippedSetCounts(equipped) {
    const counts = {};
    HV.SLOT_IDS.forEach((slot) => {
      const it = equipped && equipped[slot];
      if (it && it.set) counts[it.set] = (counts[it.set] || 0) + 1;
    });
    return counts;
  };

  HV.gatherEffects = function gatherEffects(equipped) {
    const effects = [];
    const stats = S(0);
    HV.SLOT_IDS.forEach((slot) => {
      const it = equipped && equipped[slot];
      if (!it) return;
      const st = it.stats || {};
      Object.keys(st).forEach((k) => { stats[k] = (stats[k] || 0) + (st[k] || 0); });
      (it.effects || []).forEach((e) => effects.push(Object.assign({ src: it.id }, e)));
    });
    const counts = HV.equippedSetCounts(equipped);
    Object.keys(counts).forEach((setId) => {
      const set = HV.SETS[setId];
      if (!set) return;
      const n = counts[setId];
      [2, 3, 4, 5].forEach((need) => {
        if (n >= need && set.bonuses[need]) {
          set.bonuses[need].forEach((e) => effects.push(Object.assign({ src: 'set:' + setId, setNeed: need }, e)));
        }
      });
    });
    return { stats, effects, sets: counts };
  };

