    for (let i = 0; i < N; i++) delay[i] = (Math.random() * 2 - 1);
    /* brighten the burst a little, like a picked head */
    for (let i = 1; i < N; i++) delay[i] = delay[i] * 0.7 + (delay[i] - delay[i - 1]) * 0.35;
