    let last = 0;
    const damp = opts.damp != null ? opts.damp : 0.988;
    const edge = opts.edge != null ? opts.edge : 0.28;
    for (let i = 0; i < len; i++) {
      const a = delay[idx];
      const b = delay[(idx + 1) % N];
      const y = (a + b) * 0.5 * damp;
      delay[idx] = y;
      const bright = y + (y - last) * edge;
      last = y;
      const env = i < 32 ? i / 32 : Math.exp(-i / (sr * (opts.decay || 0.7)));
      data[i] = bright * env;
      idx = (idx + 1) % N;
    }
    /* soft peak normalize */
    let peak = 0.0001;
    for (let i = 0; i < len; i++) peak = Math.max(peak, Math.abs(data[i]));
