        fillPath(ctx, () => { ctx.ellipse(0, top + 1, 11, 2.6, 0, 0, Math.PI * 2); }, hat, pal.ink, 1.4);
        fillPath(ctx, () => { ctx.ellipse(0, top - 5, 6, 5.5, 0, 0, Math.PI * 2); }, hat, pal.ink, 1.4);
