      ctx.lineWidth = 1.25;
      ctx.beginPath();
      ctx.moveTo(-2, -12);
      ctx.quadraticCurveTo(2, 2, 5, 16);
      ctx.moveTo(-7, -6);
      ctx.quadraticCurveTo(-8, 6, -6, 15);
      ctx.moveTo(6, -8);
      ctx.quadraticCurveTo(9, 4, 8, 14);
      ctx.moveTo(-4, 4);
      ctx.quadraticCurveTo(-2, 12, 0, 20);
      ctx.moveTo(3, -2);
      ctx.quadraticCurveTo(7, 8, 6, 18);
      ctx.moveTo(-9, -10);
      ctx.quadraticCurveTo(-12, 2, -10, 14);
      ctx.stroke();
      /* lantern warmth on the left hem */
      ctx.strokeStyle = 'rgba(224,123,57,0.45)';
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(-10, -4);
      ctx.quadraticCurveTo(-13, 8, -9, 16);
      ctx.stroke();
      fillPath(ctx, () => {
        ctx.moveTo(-5, -22);
        ctx.quadraticCurveTo(13, -26, 13, -14);
        ctx.quadraticCurveTo(17, -4, 14 + flap, 16);
        ctx.quadraticCurveTo(7, 24, 1, 23);
        ctx.quadraticCurveTo(-6, 25, -13 - flap, 17);
        ctx.quadraticCurveTo(-17, -2, -13, -14);
        ctx.quadraticCurveTo(-13, -26, -5, -22);
        ctx.closePath();
      }, null, pal.ink, 2.6);

      /* pointed cowl, a shade lighter than the cloak, with a face opening */
      fillPath(ctx, () => {
        ctx.moveTo(-11, -18);
        ctx.quadraticCurveTo(-13, -32, 0, -42);
        ctx.quadraticCurveTo(13, -32, 10, -16);
        ctx.quadraticCurveTo(0, -12, -11, -18);
      }, '#4A433C', pal.ink, 2.3);
      hatch(ctx, -12, -42, 24, 28, 'rgba(11,12,10,0.22)', 4.2, 48, 1);
      /* face hint in the hood — woodcut, not a portrait */
      fillPath(ctx, () => {
        ctx.moveTo(-4.2, -22);
        ctx.quadraticCurveTo(0, -31, 4.2, -22);
        ctx.lineTo(3.4, -16.5);
        ctx.quadraticCurveTo(0, -14.5, -3.4, -16.5);
        ctx.closePath();
      }, '#C4B09A', pal.ink, 1.15);
      ctx.fillStyle = 'rgba(26,20,16,0.55)';
      ctx.beginPath();
      ctx.ellipse(-1.4, -21.2, 1.15, 1.35, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = pal.ink;
      ctx.lineWidth = 0.85;
      ctx.beginPath();
      ctx.moveTo(0.6, -20.5);
      ctx.quadraticCurveTo(1.6, -19.2, 0.8, -17.8);
