      const locks = [
        { x: -7.5, y: -19, c1x: -14, c1y: -6, x2: -12, y2: 8, w: 3.6 },
        { x: -5, y: -18, c1x: -10, c1y: -4, x2: -8, y2: 11, w: 2.8 },
        { x: -2.5, y: -17, c1x: -4, c1y: -6, x2: -4, y2: 4, w: 2.2 },
        { x: 6.8, y: -19, c1x: 14, c1y: -6, x2: 12, y2: 8, w: 3.6 },
        { x: 4.2, y: -17, c1x: 10, c1y: -3, x2: 9, y2: 11, w: 2.8 },
        { x: 1.5, y: -16, c1x: 4, c1y: -6, x2: 5, y2: 3, w: 2.0 },
      ];
      locks.forEach((L) => {
        ctx.save();
        ctx.lineCap = 'round';
        ctx.strokeStyle = '#1A120E';
        ctx.lineWidth = L.w;
        ctx.beginPath();
        ctx.moveTo(L.x, L.y);
        ctx.quadraticCurveTo(L.c1x, L.c1y, L.x2, L.y2);
        ctx.stroke();
        ctx.strokeStyle = pal.ink;
        ctx.lineWidth = 1.05;
        ctx.stroke();
        ctx.restore();
      });

      /* forked yarb staff with a teal flame */
      ctx.strokeStyle = '#3A2A1C';
      ctx.lineWidth = 2.4;
      ctx.beginPath();
      ctx.moveTo(10, 16);
      ctx.lineTo(16, -32);
      ctx.stroke();
      ctx.strokeStyle = pal.ink;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(10, 16);
      ctx.lineTo(16, -32);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(16, -30); ctx.lineTo(12, -38);
      ctx.moveTo(16, -30); ctx.lineTo(21, -38);
      ctx.strokeStyle = pal.ink;
      ctx.lineWidth = 1.6;
      ctx.stroke();
