          ctx.scale(1, rh / rw);
          const g = ctx.createRadialGradient(0, 0, 2, 0, 0, rw);
          g.addColorStop(0, deep(tx, ty) ? 'rgba(6,10,14,0.45)' : 'rgba(8,14,18,0.28)');
          g.addColorStop(1, 'rgba(8,14,18,0)');
