      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(-50, 0); ctx.lineTo(-8, 50);
      ctx.moveTo(50, 0); ctx.lineTo(8, 50);
      ctx.stroke();
      ctx.restore();
