    /* Cottonmouth: smooth viper, solid body, no hatch or kinks. */
    cottonmouth(ctx, x, y, opts) {
      opts = opts || {};
      const pal = PAL();
      const facing = opts.facing >= 0 ? 1 : -1;
      const scale = (opts.scale == null || opts.scale === 1) ? 1.22 : opts.scale;
      const t = opts.t || 0;
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(facing * scale, scale);

      const slither = t * 2.4;
      const striking = Math.sin(t * 2.05) > 0.78;
      const rib = snakeRibbon(slither);
      const neck = rib.mid[rib.mid.length - 1];

      shadow(ctx, -2, 12, 18, 3.4, 0.2);

      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      const bodyG = grad(ctx, 'r', 0, 2, 1, 0, 6, 16);
      if (bodyG) { bodyG.addColorStop(0, '#2A3024'); bodyG.addColorStop(1, '#121610'); }
      strokeRibbon(ctx, rib);
      ctx.fillStyle = bodyG || '#1A1E16';
      ctx.fill();
      ctx.strokeStyle = pal.ink;
      ctx.lineWidth = 1.55;
      ctx.stroke();

      /* soft belly, a filled strip not a scratch */
      ctx.save();
      strokeRibbon(ctx, rib);
      ctx.clip();
      ctx.strokeStyle = 'rgba(120,114,98,0.55)';
      ctx.lineWidth = 2.2;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(rib.mid[2].x, rib.mid[2].y + rib.mid[2].w * 0.38);
      for (let i = 3; i < rib.mid.length - 1; i++) {
        const p = rib.mid[i];
        ctx.lineTo(p.x, p.y + p.w * 0.38);
      }
      ctx.stroke();
      /* a few soft back blotches */
      ctx.fillStyle = 'rgba(8,10,8,0.35)';
      [0.25, 0.42, 0.6].forEach((u) => {
        const k = Math.round(u * (rib.mid.length - 1));
        const p = rib.mid[k];
        ctx.beginPath();
        ctx.ellipse(p.x, p.y - p.w * 0.2, 2.8, p.w * 0.55, 0.35, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.restore();

      strokeRibbon(ctx, rib);
      ctx.strokeStyle = pal.ink;
      ctx.lineWidth = 1.55;
      ctx.stroke();

      const hx = neck.x + 4.2 + (striking ? 2.2 : 0);
      const hy = neck.y - 2.4 - (striking ? 1.2 : 0);
      const gape = striking ? 1 : 0;
      const head = () => {
        ctx.moveTo(hx - 5.4, hy + 1.6);
        ctx.quadraticCurveTo(hx - 3.2, hy - 5.6, hx + 1.6, hy - 5.2);
        ctx.quadraticCurveTo(hx + 7.4, hy - 2.4, hx + 7.0, hy + 0.4 + gape * 0.6);
        ctx.quadraticCurveTo(hx + 3.0, hy + 2.0 + gape * 3.4, hx - 5.4, hy + 1.6);
        ctx.closePath();
      };
      const hd = grad(ctx, 'r', hx, hy - 2, 1, hx, hy, 8);
      if (hd) { hd.addColorStop(0, '#2A3024'); hd.addColorStop(1, '#121610'); }
      fillGrad(ctx, head, hd, '#1A1E16', pal.ink, 1.45);

      if (striking) {
        fillPath(ctx, () => {
          ctx.moveTo(hx + 1.0, hy + 0.6);
          ctx.quadraticCurveTo(hx + 5.2, hy + 1.4, hx + 6.6, hy + 0.2);
          ctx.quadraticCurveTo(hx + 4.4, hy + 5.0, hx + 0.6, hy + 2.4);
          ctx.closePath();
        }, '#F4E8D0', pal.ink, 1);
        ctx.strokeStyle = '#8A2A1E';
        ctx.lineWidth = 1.05;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(hx + 6.6, hy + 0.5);
        ctx.lineTo(hx + 12.0, hy - 0.6);
        ctx.moveTo(hx + 9.4, hy + 0.1);
        ctx.lineTo(hx + 12.4, hy + 2.0);
        ctx.stroke();
      }

      ctx.fillStyle = pal.ember;
      ctx.beginPath();
      ctx.ellipse(hx + 1.8, hy - 1.9, 1.2, 1.0, -0.25, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = pal.ink;
      ctx.lineWidth = 0.8;
      ctx.stroke();
      ctx.fillStyle = '#0B0C0A';
      ctx.beginPath();
      ctx.arc(hx + 2.0, hy - 1.9, 0.4, 0, Math.PI * 2);
      ctx.fill();

      fillGrad(ctx, head, null, null, pal.ink, 1.45);
      ctx.restore();
    },

