      const fur = ['#8A7258', '#3A2C20'], furD = ['#5A4836', '#241A12'];
      shadow(ctx, 0, 18, 15, 3.0);
      legSet(ctx, [{ x: -10, y: 2, f: -1, claw: 2 }, { x: 8, y: 1, f: 1, claw: 2 }], step, furD);
      limb(ctx, [-13, -3], [-19, 0], [-20, 7 + br], 1.8, 0.7, fur[0], fur[1], 1.1);
      const body = [[-15, -2], [-10, -8 + br], [0, -9 + br], [9, -9], [14, -6], [13, 2], [6, 5], [-2, 3.6], [-10, 5], [-15, 3]];
      shape(ctx, body, fur[0], fur[1], 1.6);
      ctx.save(); ctx.beginPath(); blob(ctx, body); ctx.clip();
      ctx.fillStyle = 'rgba(0,0,0,0.25)';
      for (let i = 0; i < 3; i++) { ctx.beginPath(); ctx.ellipse(1 + i * 3.6, 0, 1.2, 3.0, 0.2, 0, Math.PI * 2); ctx.fill(); }
      ctx.restore();
      spikes(ctx, [[3, -9, 1, -13.6, 1.6], [6.6, -9, 5.6, -14, 1.6], [10, -8, 10, -12.4, 1.5]], fur[1]);
      rim(ctx, [[-12, -5], [-4, -8.6], [6, -8.8]], 'rgba(232,220,192,0.3)');
      legSet(ctx, [{ x: -6, y: 3, f: 1, claw: 2.2 }, { x: 11, y: 1, f: -1, claw: 2.2 }], step, fur);
      ctx.save(); ctx.translate(14, -8); ctx.rotate(0.1);
      shape(ctx, [[-4, 3], [-3, -4], [2, -6], [7, -3.6], [13, -1.6], [13.4, 1.4], [8, 2.6], [2, 5], [-2, 5.4]], fur[0], fur[1], 1.4);
      flat(ctx, [[-1, -4, 1], [-1.4, -10.6, 1], [2.6, -5.2, 1]], fur[1], 1.0);
      flat(ctx, [[8, 2.0, 1], [13.2, 1.0, 1], [12.6, 3.6, 1], [8, 4, 1]], '#3A1A14', 0.9);
