      const body = [[-17, -1], [-15, -8, 1], [-12, -6], [-10, -12, 1], [-6, -9], [-3, -14, 1], [1, -10], [4, -15, 1], [7, -10], [11, -13, 1], [14, -6], [14, 3], [6, 6], [-4, 4.6], [-12, 6], [-17, 4]];
