      const br = Math.sin(t * 1.4) * 0.8;
      const sway = Math.sin(t * 1.1) * 1.2;
      const fur = ['#3A2E26', '#0E0A08'], furL = ['#4A3C30', '#16110D'];
      glow(ctx, 6, -36, 26, 'rgba(180,24,18,0.95)', 0.45);
      shadow(ctx, -2, 21, 20, 4.4);
      /* hind legs */
      limb(ctx, [-10, 2], [-15, 10], [-14, 20], 5.2, 3.2, fur[0], fur[1], 1.6);
      limb(ctx, [3, 3], [7, 11], [5, 20], 5.2, 3.2, furL[0], furL[1], 1.6);
      claws(ctx, -12.6, 20, 1, 2.6, '#D8CCB0');
      claws(ctx, 6.4, 20, 1, 2.6, '#D8CCB0');
      /* far arm */
      limb(ctx, [-11, -18], [-23, -3 + sway], [-18, 13], 4.2, 2.6, fur[0], fur[1], 1.5);
      claws(ctx, -18, 13.6, -1, 3.6, '#E0D4B8');
      /* shaggy hulk with solid tufts */
      const body = [[-2, -42 + br], [8, -40 + br], [16, -34, 1], [15, -26], [20, -18, 1], [16, -10], [18, -2, 1], [12, 4], [8, 12, 1], [2, 9], [-6, 13, 1], [-10, 8], [-17, 9, 1], [-17, 1], [-22, -6, 1], [-18, -14], [-21, -24, 1], [-15, -30], [-14, -38, 1]];
      shape(ctx, body, fur[0], fur[1], 2.2);
      ctx.save(); ctx.beginPath(); blob(ctx, body); ctx.clip();
      ctx.fillStyle = 'rgba(0,0,0,0.28)';
