      ctx.fillStyle = 'rgba(122,96,72,0.22)';
      ctx.beginPath(); blob(ctx, [[-12, -30], [-4, -36], [-2, -26], [-10, -18]]); ctx.fill();
      ctx.restore();
      rim(ctx, [[-14, -34], [-6, -40], [6, -40]], 'rgba(232,200,170,0.3)', 1.3);
      /* near arm */
      limb(ctx, [10, -20], [22, -2 - sway], [16, 12], 4.4, 2.8, furL[0], furL[1], 1.5);
      claws(ctx, 16.4, 12.6, 1, 3.8, '#E0D4B8');
      /* head */
      const head = [[-8, -36], [-4, -48], [6, -50], [13, -44], [17, -36], [20, -30], [14, -25], [4, -25], [-6, -28]];
      shape(ctx, head, '#3A2E26', '#100C0A', 1.9);
      shape(ctx, [[9, -34], [17, -33.6], [21, -30], [18, -26], [10, -27]], '#4A3C32', '#1A1410', 1.4);
      fillPath(ctx, () => { ctx.ellipse(19.6, -30, 1.4, 1.0, 0, 0, Math.PI * 2); }, '#0B0C0A', false);
      fangs(ctx, [[13, -26.6, 2.2], [16, -26.8, 2]]);
