      legSet(ctx, [Object.assign({ x: -14, y: 2, f: -1, kx: -5, ky: -4 }, far), Object.assign({ x: 10, y: 2, f: 1, kx: -5, ky: -4 }, far)], step, ['#3E5644', '#0E1610']);
