  /* Generic wilderness builder */
  function wilderness(opt) {
    const W = opt.w || 56, H = opt.h || 42;
    const rng = HV.rng(opt.seed);
    const ground = opt.ground || '.';
    const r = gridOf(W, H, ground);
    frame(r);
    if (opt.river) {
      const startX = 4 + (rng() * (W - 8) | 0);
      meander(r, rng, startX, opt.river === 'n' ? 8 : opt.river === 's' ? H - 10 : (H >> 1), W + H, '~', opt.riverDir || 'e');
    }
    if (opt.road) {
      if (opt.road === 'ns') rect(r, (W >> 1) - 1, 1, 2, H - 2, ',');
      if (opt.road === 'ew') rect(r, 1, (H >> 1) - 1, W - 2, 2, ',');
      if (opt.road === 'cross') {
        rect(r, (W >> 1) - 1, 1, 2, H - 2, ',');
        rect(r, 1, (H >> 1) - 1, W - 2, 2, ',');
      }
    }
    if (opt.bluff) {
      const by = opt.bluff === 'n' ? 2 : H - 7;
      rect(r, 2, by, W - 4, 5, '^');
      /* a narrow trail so the cliff is reachable and a path meets the lip */
      if (opt.road === 'ns' || opt.road === 'cross') rect(r, (W >> 1) - 1, by, 2, 5, ',');
    }
    clusterSprinkle(r, rng, 'T', opt.oaks || 28, (c) => c === ground);
    clusterSprinkle(r, rng, 'C', opt.cedars || 8, (c) => c === ground);
    if (opt.sinks) sprinkle(r, rng, 's', opt.sinks, (c) => c === ground);
    /* Gravel is no longer sprinkled as contrasting gray tiles. */
    if (opt.rocks) sprinkle(r, rng, '#', opt.rocks, (c) => c === ground);
    (opt.after || []).forEach((fn) => fn(r, rng, W, H));
    return r;
  }

  function edgeExits(idMap, W, H) {
    W = W || 56; H = H || 42;
    const exits = [];
    if (idMap.n) exits.push({ x: W >> 1, y: 1, to: idMap.n, label: idMap.n });
    if (idMap.s) exits.push({ x: W >> 1, y: H - 2, to: idMap.s, label: idMap.s });
    if (idMap.e) exits.push({ x: W - 2, y: H >> 1, to: idMap.e, label: idMap.e });
    if (idMap.w) exits.push({ x: 1, y: H >> 1, to: idMap.w, label: idMap.w });
    return exits;
  }

  function areaWild(def) {
    const cells = wilderness(def.gen);
    if (def.start) set(cells, def.start.x, def.start.y, '@');
    /* punch exit tiles as path so they are walkable */
    const exits = def.exits || [];
    exits.forEach((e) => set(cells, e.x, e.y, ','));
    return add({
      id: def.id, name: def.name, subtitle: def.subtitle, biome: def.biome,
      danger: def.danger || 1, cells, exits,
      npcs: def.npcs || [],
      spawns: def.spawns || [],
      chests: def.chests || [],
      caches: def.caches || [],
      herbs: def.herbs || [],
      triggers: def.triggers || [],
      start: def.start,
    });
  }

