  /* Dungeon crawler: cellular caves with stamped rooms and a boss pad */
  function carveDungeon(seed, w, h, opt) {
    opt = opt || {};
    const rng = HV.rng(seed);
    const r = gridOf(w, h, '#');
    for (let y = 2; y < h - 2; y++) {
      for (let x = 2; x < w - 2; x++) {
        if (rng() < 0.42) set(r, x, y, 'g');
      }
    }
    /* generations */
    for (let n = 0; n < 4; n++) {
      const next = gridOf(w, h, '#');
      for (let y = 1; y < h - 1; y++) {
        for (let x = 1; x < w - 1; x++) {
          let c = 0;
          for (let j = -1; j <= 1; j++) for (let i = -1; i <= 1; i++) if (get(r, x + i, y + j) === '#') c++;
          set(next, x, y, c >= 5 ? '#' : 'g');
        }
      }
      for (let y = 0; y < h; y++) r[y] = next[y];
    }
    frame(r);
    /* rooms */
    const rooms = opt.rooms || 5;
    const placed = [];
    for (let i = 0; i < rooms; i++) {
      const rw = 6 + (rng() * 6 | 0), rh = 5 + (rng() * 5 | 0);
      const x = 3 + (rng() * (w - rw - 6) | 0);
      const y = 3 + (rng() * (h - rh - 6) | 0);
      rect(r, x, y, rw, rh, 'g');
      placed.push({ x: x + (rw >> 1), y: y + (rh >> 1) });
    }
    for (let i = 1; i < placed.length; i++) pathTo(r, placed[i - 1].x, placed[i - 1].y, placed[i].x, placed[i].y, 'g');
    if (opt.water) {
      placed.slice(-2).forEach((p) => {
        for (let k = 0; k < 12; k++) set(r, p.x + (rng() * 5 | 0) - 2, p.y + (rng() * 5 | 0) - 2, '~');
      });
    }
    const start = placed[0] || { x: 4, y: h >> 1 };
    const boss = placed[placed.length - 1] || { x: w - 6, y: h >> 1 };
    set(r, start.x, start.y, '@');
    return { cells: r, start, boss, rooms: placed };
  }

  function addDungeon(def) {
    const d = carveDungeon(def.seed, def.w || 48, def.h || 36, def);
    const exits = def.exits || [];
    exits.forEach((e) => set(d.cells, e.x, e.y, 'c'));
    const spawns = (def.spawnIds || []).map((id, i) => {
      const rm = d.rooms[1 + (i % Math.max(1, d.rooms.length - 1))] || d.boss;
      return { id, x: rm.x + (i % 3) - 1, y: rm.y + ((i * 2) % 3) - 1 };
    });
    if (def.boss) spawns.push({ id: def.boss, x: d.boss.x, y: d.boss.y, boss: true });
    return add({
      id: def.id, name: def.name, subtitle: def.subtitle, biome: 'cave', danger: def.danger || 3,
      cells: d.cells, start: d.start, exits,
      spawns, chests: def.chests || [{ id: def.id + '_chest', x: d.boss.x + 2, y: d.boss.y, table: 'boss' }],
      caches: def.caches || [{ id: def.id + '_cache', x: d.start.x + 3, y: d.start.y, table: 'cache', hidden: true }],
      dark: true,
    });
  }

