      ctx.quadraticCurveTo(x + s * 0.9, y - s * 0.3, x, y - s * 1.38);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = pal.ink;
      ctx.lineWidth = 1.3;
      ctx.stroke();
