      ctx.strokeStyle = 'rgba(224,123,57,0.7)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(x + towardFire * s * 0.15, y - s * 1.2);
      ctx.quadraticCurveTo(x + towardFire * s * 0.7, y - s * 0.4, x + towardFire * s * 0.55, y);
