    ctx.fillStyle = pal.gold;
    ctx.fillText(String(this.score), hudX, hudY + 6);
    ctx.font = (short ? '12px ' : '14px ') + serif;
    ctx.fillStyle = this.mul > 1 ? pal.gold : pal.tan;
    ctx.font = ((short ? '12px ' : '14px ') + serif);
