    ctx.fillStyle = '#140F0C';
    ctx.fillRect(hudX, hudY + 32, 120, 8);
    ctx.strokeStyle = pal.ink;
    ctx.strokeRect(hudX, hudY + 32, 120, 8);
    ctx.fillStyle = pal.gold;
    ctx.fillRect(hudX, hudY + 32, 120 * (this.roll / 100), 8);
    ctx.fillStyle = pal.tan;
    ctx.font = '11px ' + serif;
    ctx.fillText(this.roll >= 50 ? 'Tap ROLL' : 'ROLL', hudX, hudY + 54);

    const mxb = hudX, myb = hudY + 64, mw = 120, mh = 8;
    ctx.fillStyle = '#140F0C';
    ctx.fillRect(mxb, myb, mw, mh);
    ctx.strokeStyle = pal.tan;
    ctx.lineWidth = 1.5;
    ctx.strokeRect(mxb - 0.5, myb - 0.5, mw + 1, mh + 1);
    ctx.strokeStyle = pal.ink;
    ctx.lineWidth = 1;
    ctx.strokeRect(mxb - 0.5, myb - 0.5, mw + 1, mh + 1);
    ctx.fillStyle = this.meter < 20 ? pal.blood : this.meter >= 40 ? pal.forestLit : pal.ember;
    ctx.fillRect(mxb, myb, mw * (this.meter / 100), mh);
    ctx.font = '11px ' + serif;
    ctx.fillStyle = pal.tan;
    ctx.textAlign = 'left';
    ctx.fillText('KEEP', mxb, myb + 20);

