      ctx.textAlign = 'center';
      ctx.fillStyle = pal.parchment;
      ctx.font = (short ? '12px ' : '14px ') + serif;
      ctx.letterSpacing = '0.04em';
      ctx.fillText('Song: ' + this.song.name, w / 2, short ? 16 : 20);
