      ctx.globalAlpha = life;
      ctx.textAlign = 'center';
      ctx.font = 'italic ' + (short ? '14px ' : '16px ') + serif;
      ctx.fillStyle = this.banner === 'LISTEN' ? pal.haint : pal.gold;
      ctx.strokeStyle = 'rgba(11,12,10,0.65)';
