      this._toastUntil = (typeof performance !== 'undefined' ? performance.now() : Date.now()) + next.ms;
      if (this._toastYielded) { this._toastPaused = true; this._toastRemain = next.ms; this._tt = null; return; }
      this._tt = setTimeout(() => self._pumpToast(), next.ms);
