        const scale = Math.min(ir.width / nw, ir.height / nh);
        const dw = nw * scale, dh = nh * scale;
        const ox = ir.left + (ir.width - dw) * 0.5;
        const oy = ir.top;
        fx.style.left = (ox - wrapR.left) + 'px';
        fx.style.top = (oy - wrapR.top) + 'px';
        fx.style.width = dw + 'px';
