    return '<div class="hv-frame">'
      + '<div class="hv-frame-mono">' + mono + '</div>'
      + (label ? '<div class="hv-frame-cap">' + label + '</div>' : '')
      + (sub ? '<div class="hv-frame-sub">' + sub + '</div>' : '')
