    josie: { npc: 'josie', area: 'yarrow_crossing', every: 9, range: 150,
      join: 'Josie Fiddler walks with you. When a fight starts she plays: foes slow, and you mend a little.',
      can: (s) => HV.questDone(s, 'josie_string'),
      teaser: 'Josie Fiddler lost her mother\'s silver string in the burned mill. Bring it back and she will walk the roads with you.' },
    wren: { npc: 'sheriff', area: 'yarrow_crossing', every: 6.5, range: 190,
      join: 'Sheriff Wren rides along. He takes a careful shot when something comes at you.',
      can: (s) => !!s.flags.met_wren && HV.Companions.approval(s, 'wren') >= 40,
      teaser: 'Sheriff Wren would ride with you once he trusts you. Talk to him in Yarrow.' },
    cole: { npc: 'ferryman', area: 'ferry_crossing', every: 7.5, range: 120,
      join: 'Ferryman Cole comes along with his pole. He knocks foes back and holds them a moment.',
      can: (s) => (!!s.flags.caught_light || !!(s.quests && s.quests.spook_light)) && HV.Companions.approval(s, 'cole') >= 35,
      teaser: 'Ferryman Cole might leave the cable a while. Earn his trust at the Ferry Crossing.' },
