      if (!F._pos || Math.hypot(F._pos.x - hx, F._pos.y - hy) > 220 || F._pos.stuck > 1.2) F._pos = { x: tx, y: ty, facing: fc, moving: false, cd: F._pos ? F._pos.cd : 3, act: 0, actKind: null, stuck: 0 };
