      [s1, s2].forEach((s) => { s.o.disconnect(); s.o.connect(lp); }); lp.connect(s1.g); s1.g.gain.value = 0.03; graph.nodes.push(lp);
      mod(c, lp.frequency, 0.13, 90, graph);
