    const push = (name, min, max, fn) => base.push({ name: name, min: min, max: max, fn: fn });
    const E = S.EV;
    if (kind === 'woods' || kind === 'woods_dark') { if (!isNight) push('katydid', 6, 14, E.katydidDay); else push('howl', 25, 60, E.howlFar); }
    if (kind === 'bluff' && isNight) push('howl', 30, 70, E.howlFar);
    if (kind === 'town') { push('clink', 14, 30, E.clink); push('hammer', 18, 40, E.hammer); if (!isNight) push('hen', 16, 36, E.hen); }
    if (kind === 'river' || kind === 'cave_river') push('burble', 3, 8, E.burble);
    if (kind === 'churchyard') { push('bell', 30, 60, E.bell); push('crow', 12, 28, E.crow); push('wail', 14, 30, (s, t) => { tn(t, 1.8, 0.02, 'sine', 330, 294, amb(), 0.5); tn(t + 0.3, 1.6, 0.014, 'sine', 392, 349, amb(), 0.5); }); }
    if (kind === 'gallows') { push('rope', 4, 10, E.rope); push('crow', 10, 24, E.crow); }
