    ctx.lineTo(-8 + 1.2, -8 - 1.2);
    ctx.lineTo(-8 + r, -8);
    ctx.lineTo(-8 + 1.2, -8 + 1.2);
    ctx.lineTo(-8, -8 + r);
    ctx.lineTo(-8 - 1.2, -8 + 1.2);
    ctx.lineTo(-8 - r, -8);
    ctx.lineTo(-8 - 1.2, -8 - 1.2);
