/* ---- folded from 37-hv49.js (hv96 cleanup part 2; behaviour unchanged) ---- */
/* hv49: Hardscrabble (a real hard mode) + Endings Found on the title.
   Ids stay put for old saves: 'hollow' is shown as Normal, 'hard' as Hardscrabble. */
(function (root) {
  'use strict';
  const HV = root.HV;

  /* ---------- difficulty numbers ---------- */
  const NORMAL = { find: 1, resource: 1, shop: 1, heal: 1, aggro: 1, speed: 1, p2At: 0.5, stagger: 1.0, deathCoin: 0, wakeHp: 0.6 };
  const HARD = { enemyHp: 1.4, dmg: 1.35, find: 0.6, resource: 0.75, shop: 1.35, heal: 0.85, aggro: 1.35, speed: 1.1, p2At: 0.6, stagger: 0.7, deathCoin: 1 / 3, wakeHp: 0.4 };
  const D = HV.DIFFICULTY;
  Object.assign(D.story, NORMAL, { find: 1.2, resource: 1.25, shop: 0.9 });
  Object.assign(D.hollow, NORMAL, { name: 'Normal' });
  Object.assign(D.hard, HARD, { name: 'Hardscrabble' });
  Object.assign(D.iron, HARD, { name: 'Iron Lantern', permadeath: true });
  HV.HARD_NUMBERS = HARD;

  HV.diffOf = function (state) {
    const id = state && state.difficulty;
    return D[id] || D.hollow;
  };
  HV.diffName = function (id) { return (D[id] || D.hollow).name; };
  HV.isHardRoad = (state) => !!(state && (state.difficulty === 'hard' || state.difficulty === 'iron'));

  /* enemies: a touch quicker and they notice you from further off */
  const _spawn = HV.spawnEnemy;
  HV.spawnEnemy = function (id, x, y, mods) {
    const en = _spawn.apply(this, arguments);
    const d = (mods && mods.difficulty) || D.hollow;
    if (en) {
      if (d.speed && d.speed !== 1) en.speed = Math.round(en.speed * d.speed * 100) / 100;
      en._aggroMul = d.aggro || 1;
    }
    return en;
  };

  /* shops charge more on the hard road */
  const _buy = HV.buyPrice;
  HV.buyPrice = function (it, state) {
    const base = _buy.apply(this, arguments);
    const mul = state ? (HV.diffOf(state).shop || 1) : 1;
    return Math.max(1, Math.round(base * mul));
  };

  /* props: fewer poultices and herbs, leaner coin */
  if (HV.Breakables && HV.Breakables.rollDrop) {
    const B = HV.Breakables, _roll = B.rollDrop;
    B.rollDrop = function (state, prop, area, rng) {
      rng = rng || Math.random;
      const out = _roll.call(this, state, prop, area, rng);
      const d = HV.diffOf(state);
      if (out && (out.tier === 'potion' || out.tier === 'herb') && (d.find || 1) < 1 && rng() > d.find) { out.item = null; out.tier = 'coin'; }
      if (out && d.resource && d.resource !== 1) out.coins = Math.max(1, Math.round(out.coins * d.resource));
      return out;
    };
  }

  /* ---------- Endings Found (kept across saves and New Game+) ---------- */
  const E = HV.EndingsFound = {
    KEY: 'hollowVeil.endings.v1',
    ORDER: ['seal', 'purge', 'warden', 'tear', 'drown', 'true_sign'],
    store() { try { return (typeof localStorage !== 'undefined') ? localStorage : null; } catch (e) { return null; } },
    read() {
      const s = E.store(); if (!s) return {};
      try { const o = JSON.parse(s.getItem(E.KEY) || '{}'); return (o && o.found) || {}; } catch (e) { return {}; }
    },
    record(id) {
      if (!id || !HV.ENDINGS || !HV.ENDINGS[id]) return false;
      const s = E.store(); if (!s) return false;
      const f = E.read();
      if (f[id]) return false;
      f[id] = Date.now();
      try { s.setItem(E.KEY, JSON.stringify({ found: f })); } catch (e) { return false; }
      return true;
    },
    /* old saves: anything already finished counts (the NG+ carry, autosave, slots) */
    backfill() {
      const look = (r) => { const st = r && (r.ok ? (r.data && r.data.state) : (r.flags ? r : null)); if (st && st.flags && st.flags.ending) E.record(st.flags.ending); };
      try { if (HV.Save && HV.Save.loadNgCarry) look(HV.Save.loadNgCarry()); } catch (e) { /* none */ }
      try { if (HV.Save && HV.Save.loadAuto) look(HV.Save.loadAuto()); } catch (e) { /* none */ }
      try { if (HV.Save && HV.Save.loadSlot) for (let n = 1; n <= (HV.Save.SLOT_COUNT || 3); n++) look(HV.Save.loadSlot(n)); } catch (e) { /* none */ }
    },
    list() {
      const f = E.read();
      return E.ORDER.map((id) => ({ id, found: !!f[id], title: f[id] ? HV.ENDINGS[id].title : null }));
    },
    count() { return E.list().filter((x) => x.found).length; },
    sealsHtml(opts) {
      opts = opts || {};
      const l = E.list();
      if (opts.current) l.forEach((x) => { if (x.id === opts.current) x.found = true; });
      const n = l.filter((x) => x.found).length;
      if (!n && !opts.always) return '';
      const cap = (t) => (t || '').toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase());
      const cls = opts.className || 'title-endings';
      return '<div class="' + cls + '" role="img" aria-label="Endings found: ' + n + ' of ' + l.length + '">'
        + '<span class="te-plank">'
        + l.map((x) => x.found
          ? '<span class="te-seal is-found te-' + x.id + '" title="' + cap(x.title) + '"></span>'
          : '<span class="te-seal is-unknown" title="Not yet found"></span>').join('')
        + '</span><span class="te-count">' + n + ' of ' + l.length + ' endings</span></div>';
    },
    html() { return E.sealsHtml(); },
  };

  const G = HV.Game;
  if (G && G.finishGame && !G.finishGame._hv49) {
    const _fin = G.finishGame;
    G.finishGame = function (forced) {
      const r = _fin.apply(this, arguments);
      try { E.record(this.state && this.state.flags && this.state.flags.ending); } catch (e) { /* ignore */ }
      return r;
    };
    G.finishGame._hv49 = true;
  }
  if (HV.UI && HV.UI.showTitle && !HV.UI.showTitle._hv49) {
    const _title = HV.UI.showTitle;
    HV.UI.showTitle = function () {
      const r = _title.apply(this, arguments);
      try {
        if (!E._backfilled) { E._backfilled = true; E.backfill(); }
        const screen = typeof document !== 'undefined' && document.querySelector('#title-screen');
        const h = E.html();
        if (screen && h && !screen.querySelector('.title-endings')) {
          screen.classList.add('has-endings');
          const gear = screen.querySelector('.title-settings');
          if (gear) gear.insertAdjacentHTML('beforebegin', h);
          else screen.insertAdjacentHTML('beforeend', h);
        }
      } catch (e) { /* the title still works without it */ }
      return r;
    };
    HV.UI.showTitle._hv49 = true; HV.UI.showTitle._orig = _title;
  }
})(typeof window !== 'undefined' ? window : globalThis);

