      try { if (HV.Save && HV.Save.loadSlot) for (let n = 1; n <= (HV.Save.SLOT_COUNT || 3); n++) { const r = HV.Save.loadSlot(n); look(r && r.ok && r.data && r.data.state); } } catch (e) { /* none */ }
