    stroke(() => { ctx.moveTo(-22, -118); ctx.lineTo(22, -118); ctx.lineTo(26, -96); ctx.lineTo(-26, -96); ctx.closePath(); }, '#2A2620', 2.2);
    stroke(() => { ctx.moveTo(-58, -70); ctx.quadraticCurveTo(0, -118, 58, -70); ctx.lineTo(50, -48); ctx.lineTo(-50, -48); ctx.closePath(); }, '#2C2822', 2.6);
    ctx.fillStyle = '#1A1410';
