/* hv63: Pack item thumbs — real plates when we have them, woodcut
   category glyphs when we don't. Never an empty or broken box. */
(function (root) {
  'use strict';
  const HV = root.HV = root.HV || {};

  const GLYPH = HV.PACK_GLYPHS = HV.PACK_GLYPHS || {};
  GLYPH.staff = "art/staff.webp";
  GLYPH.staff_bytes = 10178;
  GLYPH.coat = "art/coat.webp";
  GLYPH.coat_bytes = 30028;
  GLYPH.boots = "art/boots.webp";
  GLYPH.boots_bytes = 27084;
  GLYPH.charm = "art/charm.webp";
  GLYPH.charm_bytes = 15014;
  GLYPH.ring = "art/ring.webp";
  GLYPH.ring_bytes = 17084;
  GLYPH.lantern = "art/lantern.webp";
  GLYPH.lantern_bytes = 16986;
  GLYPH.herb = "art/herb.webp";
  GLYPH.herb_bytes = 24764;
  GLYPH.consumable = "art/consumable.webp";
  GLYPH.consumable_bytes = 18308;
  GLYPH.quest = "art/quest.webp";
  GLYPH.quest_bytes = 16614;
  GLYPH.misc = "art/misc.webp";
  GLYPH.misc_bytes = 30110;
  GLYPH.empty = "art/empty.webp";
  GLYPH.empty_bytes = 4772;

  HV.itemArtId = function (it) {
    if (!it) return null;
    const tryId = (id) => (id && HV.artUrl && HV.artUrl(id)) ? id : null;
    let found = tryId(it.art);
    if (found) return found;
    const def = (HV.ITEM_BY_ID && (HV.ITEM_BY_ID[it.id] || HV.ITEM_BY_ID[it.herbId])) || null;
    if (def) { found = tryId(def.art); if (found) return found; }
    const herb = HV.HERB_BY_ID && (HV.HERB_BY_ID[it.herbId] || HV.HERB_BY_ID[it.id]);
    if (herb) { found = tryId(herb.art); if (found) return found; }
    return null;
  };

  HV.packGlyphKind = function (it) {
    if (!it) return 'empty';
    const def = (HV.ITEM_BY_ID && (HV.ITEM_BY_ID[it.id] || HV.ITEM_BY_ID[it.herbId])) || it;
    const slot = it.slot || def.slot;
    if (slot === 'staff') return 'staff';
    if (slot === 'coat') return 'coat';
    if (slot === 'boots') return 'boots';
    if (slot === 'charm') return 'charm';
    if (slot === 'ring') return 'ring';
    if (slot === 'lantern') return 'lantern';
    const cat = (HV.itemCategory && HV.itemCategory(it)) || 'misc';
    if (cat === 'herbs') return 'herb';
    if (cat === 'consumables') return 'consumable';
    if (cat === 'quest') return 'quest';
    if (cat === 'weapons') return 'staff';
    if (cat === 'armor') return 'coat';
    if (cat === 'charms') return slot === 'ring' ? 'ring' : 'charm';
    return 'misc';
  };

  HV.itemThumbHtml = function (it) {
    const artId = HV.itemArtId(it);
    const kind = HV.packGlyphKind(it);
    const src = artId
      ? HV.artUrl(artId)
      : (GLYPH[kind] || GLYPH.misc);
    const cls = 'pack-thumb' + (artId ? ' is-art' : ' is-glyph') + (!it ? ' is-empty' : '');
    const alt = it ? String(it.name || it.id || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;') : '';
    const qty = (it && it.qty > 1) ? '<span class="pack-thumb-qty">' + it.qty + '</span>' : '';
    return '<span class="' + cls + '"><img src="' + src + '" alt="' + alt + '" draggable="false">' + qty + '</span>';
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = HV;
})(typeof window !== 'undefined' ? window : globalThis);

