    snawfus: { art: 'boss_snawfus', title: 'THE SNAWFUS', line: 'A white deer with flowering antlers, and a breath of blue smoke where it steps.' },
    whitey: { art: 'boss_whitey', title: 'WHITEY', line: 'A grey-white horned beast of the underground river, spined and plated, pale as a drowned moon.' },
