    Book.ensure(state);
    const p = document.createElement('div');
    p.className = 'wood-panel hv-scroll-panel cb-root';
    p.style.cssText = 'width:min(640px,96vw);padding:0;overflow:hidden';
    let section = opts.section || 'haints';
    let page = (opts.page != null) ? opts.page : null;
    let mode = opts.mode || (page == null ? 'index' : 'page');
    const paint = () => {
      p.innerHTML = Book.html(state, section, page, mode);
      const go = (sec, pg, md) => { section = sec; page = pg; mode = md; paint(); };
      const close = p.querySelector('#cb-close');
      if (close) close.addEventListener('click', () => {
        if (opts.close) opts.close();
        else { HV.UI.hideOverlay(); if (opts.game) opts.game.mode = 'play'; }
      });
      p.querySelectorAll('[data-cb-tab]').forEach((b) => {
        b.addEventListener('click', () => go(b.getAttribute('data-cb-tab'), null, 'index'));
      });
      p.querySelectorAll('[data-cb-jump]').forEach((b) => {
        b.addEventListener('click', () => go(section, +b.getAttribute('data-cb-jump'), 'page'));
      });
      const open = p.querySelector('#cb-open');
      if (open) open.addEventListener('click', () => go(section, 0, 'page'));
      const idx = p.querySelector('#cb-index');
      if (idx) idx.addEventListener('click', () => go(section, null, 'index'));
      const prev = p.querySelector('#cb-prev');
      if (prev) prev.addEventListener('click', () => go(section, Math.max(0, (page || 0) - 1), 'page'));
      const next = p.querySelector('#cb-next');
      if (next) next.addEventListener('click', () => go(section, (page || 0) + 1, 'page'));
      Book.inkifyRoot(p);
    };
    paint();
    if (opts.game) opts.game.mode = 'book';
    HV.UI.showOverlay(p, false);
    return p;
