    snakeroot_blood: { name: 'Snakeroot Blood', line: 'You cannot be poisoned.', block: ['poison'], hud: 'safe from Poison' },
    second_wind: { name: 'Second Wind', line: 'Once, a blow that would knock you out leaves you at 1 Blood.', lastStand: true, hud: 'one blow can\'t drop you' },
    sure_foot: { name: 'Sure Foot', line: 'You walk faster and meet about 30% fewer wild fights.', speedMul: 1.1, fewerFights: 0.3, hud: 'quick feet, fewer fights' },
    keen_eye: { name: 'Keen Eye', line: 'Double from forage and herbs, more coin and loot from fights.', gatherMul: 2, find: 10, coinMul: 1.25, lootChance: 0.15, hud: 'double forage, more loot' },
