    for (const id in items) { if (items[id] && !kit[id]) return true; }
    const crit = state.foundCritters || {};
    for (const id in crit) { if (crit[id]) return true; }
    const parts = bookCounts(state);
    if (parts.haints && parts.haints.have > 0) return true;
    const best = state.bestiary || {};
