      const pal = (HV.PAL) || {};
      const ink = pal.ink || '#0B0C0A';
      ctx.save();
      ctx.translate(x, y);
      if (HV.Light && HV.Light.cast) HV.Light.cast(ctx, 0, 4, 10, 3.2, 0.22);
      ctx.fillStyle = '#3A2A1C';
      ctx.fillRect(-3, -30, 6, 34);
      ctx.strokeStyle = ink;
      ctx.lineWidth = 1.6;
      ctx.strokeRect(-3, -30, 6, 34);
      ctx.beginPath();
      ctx.moveTo(3, -26);
      ctx.lineTo(14, -26);
      ctx.lineTo(14, -20);
      ctx.strokeStyle = ink;
      ctx.lineWidth = 1.6;
      ctx.lineCap = 'round';
      ctx.stroke();
      ctx.fillStyle = '#1A1410';
      ctx.fillRect(10, -20, 8, 10);
      ctx.strokeStyle = ink;
      ctx.lineWidth = 1.3;
      ctx.strokeRect(10, -20, 8, 10);
      ctx.fillStyle = pal.gold || '#C9A227';
      ctx.fillRect(12, -18, 4, 5);
      const lf = 1 + Math.sin((t || 0) * 8.5) * 0.18;
      ctx.save();
      ctx.translate(14, -14);
      ctx.scale(lf, lf);
      ctx.fillStyle = '#F4E8C0';
      ctx.beginPath();
      ctx.moveTo(0, 1.6);
