    const stage = q ? (q.stage || 0) : 0;
    const marks = markCount(state);
    let progress;
    if (!flags.ila_briefed && stage <= 0) progress = 'The Thinning has not yet begun.';
    else if (marks < 3) progress = 'The three marks · ' + marks + ' of 3';
    else if (!HV.hasChosenSide || !HV.hasChosenSide(state)) progress = 'The three marks · 3 of 3';
    else if (stages.length) progress = 'The Thinning · ' + Math.min(stage + 1, stages.length) + ' of ' + stages.length;
